{"source":"def overlap_seconds(start_a, end_a, start_b, end_b):
    if end_a < start_a or end_b < start_b:
        raise ValueError("invalid")
    low = max(start_a, start_b)
    high = min(end_a, end_b)
    if high <= low:
        return 0
    return high - low
def bucket_index(timestamp, origin, width):
    if width <= 0:
        raise ValueError("invalid")
    return (timestamp - origin) // width
def remaining_ttl(now, created, ttl):
    if ttl < 0:
        raise ValueError("invalid")
    elapsed = now - created
    if elapsed < 0:
        return ttl
    remaining = ttl - elapsed
    if remaining < 0:
        return 0
    if remaining > ttl:
        return ttl
    return remaining
